const test=require('node:test'),assert=require('node:assert/strict');
test('organic Town growth is repeatable, non-grid, non-overlapping and retains earlier homes',async()=>{const {TOWN_LAYOUTS,townLayout,townRoute,layoutSites}=await import('../town-life/layouts.mjs');for(const id of Object.keys(TOWN_LAYOUTS))for(const seed of [1,7,41,79,7960]){const full=townLayout(id,seed),early=townLayout(id,seed,0);assert.equal(early.homes.length,2);assert.deepEqual(early.homes,full.homes.slice(0,2));assert.deepEqual(townLayout(id,seed),full);assert(full.homes.some(h=>Math.abs(h.angle/(Math.PI/6)-Math.round(h.angle/(Math.PI/6)))>.05));for(const h of full.homes){for(const q of full.homes)if(q!==h)assert(Math.hypot(h.center[0]-q.center[0],h.center[1]-q.center[1])>=8.8);for(const target of Object.values(layoutSites(id,seed))){const path=townRoute(id,h.door,target,seed);assert.deepEqual(path.at(-1),target);}}assert.notDeepEqual(full.homes,townLayout(id,seed+1).homes);}});
test('shared spatial agents move on the rendered paths and report actual distance',async()=>{const T=await import('../vendor/three.module.js'),{attachSceneLife,animateSceneLife}=await import('../microcosm-view.mjs'),{spatialState,spatialReadout}=await import('../microcosm.mjs');const state=spatialState(),plan={center:{x:0,z:0},seed:4,placements:[{}],paths:[{points:[{x:0,z:0},{x:3,z:4}],width:2}]},g=new T.Group();attachSceneLife(g,plan,()=>state,()=>2);animateSceneLife(g,5);assert.equal(state.seconds,5);assert(Math.abs(state.metres-6)<.001);assert.equal(state.trips,1);assert(Math.abs(g.children[0].children[0].position.y-2.04)<.1);assert.deepEqual(spatialReadout([plan]),{sites:1,routes:1,metres:5});});
test('new Town terrain is seamless outside its hex and foundations are flat',async()=>{const {TOWN_LAYOUTS,townLayout,townElevation}=await import('../town-life/layouts.mjs');for(const id of Object.keys(TOWN_LAYOUTS)){const d=townLayout(id,41);assert.equal(townElevation(id,41,44,0),0);for(const h of d.homes){const [x,z]=h.center;assert(Math.abs(townElevation(id,41,x,z)-townElevation(id,41,x+.5,z))<.01);}}});
